# ---------------------------------------------------------------- помощники разметки топологий
def N(i, t, x, y, l=None, lp=None, **k):
    d = {"i": i, "t": t, "x": x, "y": y}
    if l: d["l"] = l
    if lp: d["lp"] = lp
    d.update(k); return d

def CL(i, x, y, w, h, l="", **k):
    d = {"i": i, "t": "cloud", "x": x, "y": y, "w": w, "h": h, "l": l}; d.update(k); return d

def E(a, b, c="", **k):
    d = {"a": a, "b": b, "c": c}; d.update(k); return d

def T(x, y, s, c="", a="middle", z=None, **k):
    d = {"x": x, "y": y, "s": s, "c": c, "a": a}
    if z: d["z"] = z
    d.update(k); return d

def PT(pid, d, c="", **k):
    r = {"id": pid, "d": d, "c": c}; r.update(k); return r

def draw(t, pid, ms=800): return [t, "draw", pid, ms]
def pkt(t, uid, pid, ms, pk="a", a=0, b=1, hide=False):
    return [t, "pkt", f"#{uid}-{pid}-f", ms, f"#{uid}-{pk}", a, b, "hide" if hide else None]
def on(t, sel): return [t, "on", sel]
def off(t, sel): return [t, "off", sel]
def add(t, sel, c): return [t, "add", sel, c]
def rm(t, sel, c): return [t, "rm", sel, c]
def hl(t, tab, r): return [t, "hl", tab, r]
def scan(t, tab, rows, st=420): return [t, "scan", tab, rows, st]
def txt(t, sel, s): return [t, "txt", sel, s]


